  ],
  "steps": [
    {
      "name": "CLAMP (M201)",
      "entry": "Pallet arrives in test position (ZS-2008 / X23 rising edge) while auto mode active (SS-0003 / X2), no ST20 fault (M299), and station idle (not M200)",
      "exit": "Clamp confirmed closed (ZS-2002A / X20 made) and clamp open clear (ZS-2002B / X21 clear)"
    },
    {
      "name": "FILL (M202)",
      "entry": "Clamp closed confirmation satisfied from CLAMP step",
      "exit": "PT-2001 reaches fill threshold (D100 >= D122 / 14.50 kPa) or aborts on fault/timeout"
    },
    {
      "name": "STABILISE (M203)",
      "entry": "Fill complete condition met (D100 >= D122)",
      "exit": "Stabilisation timer done (T22)"
    },
    {
      "name": "TEST (M204)",
      "entry": "Stabilisation timer elapsed (T22)",
      "exit": "Test window timer done (T23)"
    },
    {
      "name": "VENT (M205)",
      "entry": "Test window timer elapsed (T23) or abort condition triggered by active fault (M299)",
      "exit": "Vent timer elapsed (T200), pack pressure vented below 1.00 kPa (D100 < K100), and PT-2001 healthy (not M292)"
    },
    {
      "name": "UNCLAMP (M206)",
      "entry": "Vent conditions satisfied",
      "exit": "Clamp confirmed open (ZS-2002B / X21 made) and clamp closed clear (ZS-2002A / X20 clear)"
    },
    {
      "name": "DONE (M207)",
      "entry": "Unclamp confirmed open satisfied",
      "exit": "Pallet leaves test position (ZS-2008 / X23 lost)"
    }
  ],
  "interlocks": [
    {
      "cause": "Pallet arrives when not in auto, fault active, or station busy",
      "effect": "Cycle start inhibited"
    },
    {
      "cause": "Clamp closed confirmation lost during fill",
      "effect": "Fill valve closes immediately"
    },
    {
      "cause": "Pack pressure not below 1.00 kPa or PT-2001 signal fault during vent",
      "effect": "Station holds in VENT step with vent open, unclamp inhibited"
    },
    {
      "cause": "ST20 fault active (M299) while cycle busy",
      "effect": "Cycle aborts directly to VENT step with latched FAIL result"
    },
    {
      "cause": "Manual vent PB-2010 (X25) pressed while not in auto mode (X2)",
      "effect": "Vent valve (Y22) opens manually"
    }
  ],
  "alarms": [
    {
      "name": "Fill timeout",
      "condition": "Test pressure not reached within fill timeout timer (T21 / 8.0 s)",
      "action": "Set M290, abort to VENT, FAIL"
    },
    {
      "name": "Over-pressure",
      "condition": "PT-2001 reading above overpressure threshold (D100 > D123 / 20.00 kPa)",
      "action": "Set M291 (latched), fill valve closed, vent valve held open, abort to VENT, FAIL"
    },
    {
      "name": "PT-2001 signal fault",
      "condition": "PT-2001 reading below -5.00 kPa (D100 < K-500)",
      "action": "Set M292, inhibit cycle start, hold station in VENT / inhibit unclamp"
    },
    {
      "name": "Supply air low",
      "condition": "PS-2009 (X22) lost while ST20 is busy (M200)",
      "action": "Set M293 (latched), abort to VENT, FAIL"
    }
  ],
  "conflicts": [
    {
      "item": "stabilise_time",
      "narrative_says": "3 s",
      "parameter_sheet_says": "5.0 s (T22)",
      "program_says": "5.0 s (OUT T22 K50)",
      "authoritative": "parameter sheet"
    },
    {
      "item": "test_pressure",
      "narrative_says": "15.2 kPa",
      "parameter_sheet_says": "15.00 kPa(g) (regulator PR-2012 mechanical, note mentions 15.2 kPa)",
      "program_says": "N/A (regulated mechanically)",
      "authoritative": "parameter sheet"
    },
    {
      "item": "vent_time",
      "narrative_says": "0.5 s",
      "parameter_sheet_says": "0.5 s (T24)",
      "program_says": "5.0 s on FX5U (R21 uses OUT T200 K50, which is a 100 ms timer base = 5.0 s instead of 0.5 s)",
      "authoritative": "parameter sheet"
    }
  ]
}
